import React, { useState } from 'react';
import './Calendar.css';

const Calendar = ({ selectedDate, onDateSelect, todos }) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());

  const getDaysInMonth = (date) => {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (date) => {
    return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  };

  const getTodayDate = () => new Date();

  const hasTodos = (day) => {
    const dateStr = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day)
      .toISOString().split('T')[0];
    return todos.some(todo => todo.date === dateStr);
  };

  const previousMonth = () => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1));
  };

  const nextMonth = () => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1));
  };

  const daysInMonth = getDaysInMonth(currentMonth);
  const firstDay = getFirstDayOfMonth(currentMonth);
  const daysArray = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const emptyDays = Array.from({ length: firstDay }, (_, i) => null);

  const monthName = currentMonth.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

  return (
    <div className="calendar">
      <div className="calendar-header">
        <button onClick={previousMonth} className="nav-btn">◀</button>
        <h3>{monthName}</h3>
        <button onClick={nextMonth} className="nav-btn">▶</button>
      </div>

      <div className="weekdays">
        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
          <div key={day} className="weekday">{day}</div>
        ))}
      </div>

      <div className="days-grid">
        {[...emptyDays, ...daysArray].map((day, index) => {
          const date = day ? new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day) : null;
          const isSelected = selectedDate && date ? date.toDateString() === selectedDate.toDateString() : false;
          const isToday = date ? date.toDateString() === getTodayDate().toDateString() : false;
          const hasTodo = day && hasTodos(day);

          return (
            <div
              key={index}
              className={`day ${isSelected ? 'selected' : ''} ${isToday ? 'today' : ''} ${hasTodo ? 'has-todos' : ''}`}
              onClick={() => date && onDateSelect(date)}
            >
              {day && (
                <>
                  <div className="day-number">{day}</div>
                  {hasTodo && <div className="todo-indicator">•</div>}
                </>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Calendar;
